+        if (cancel != nullptr && cancel->load()) {
+            out.error = "Upload canceled";
+        } else if (!WinHttpSendRequest(request, headers.c_str(), static_cast<DWORD>(-1),
+                                       WINHTTP_NO_REQUEST_DATA, 0, total, 0)) {
