+    size_t i = 0;
+    while (i < path.size()) {
+        size_t len = utf8_codepoint_len(static_cast<unsigned char>(path[i]));
+        if (i + len > path.size()) {
+            len = 1;
+        }
+        i += len;
+        const std::string tail = std::string(kHostFstEllipsis) + path.substr(i);
+        if (static_cast<float>(tr->string_width(tail)) <= max_w) {
+            return tail;
+        }
